insert into collections (id, slug, name, description, image_url, season) values ('c1', 'noir-essentials', 'Noir Essentials', 'The quiet foundation of every wardrobe. Precise cuts in matte black and deep charcoal — pieces that earn their place by lasting decades.', '/collection-1.jpg', 'Autumn / Winter 2025') on conflict (id) do update set slug=excluded.slug, name=excluded.name, description=excluded.description, image_url=excluded.image_url, season=excluded.season;
insert into collections (id, slug, name, description, image_url, season) values ('c2', 'the-ivory-edit', 'The Ivory Edit', 'Warm whites and natural oatmeal tones shaped into an edit of effortless ease. Each piece holds light differently depending on how you move.', '/collection-2.jpg', 'Spring / Summer 2025') on conflict (id) do update set slug=excluded.slug, name=excluded.name, description=excluded.description, image_url=excluded.image_url, season=excluded.season;
insert into collections (id, slug, name, description, image_url, season) values ('c3', 'soiree-noire', 'Soirée Noire', 'After-dark dressing without excess. Evening silhouettes cut with architectural restraint — made to be remembered for what they leave out.', '/collection-3.jpg', 'Resort 2025') on conflict (id) do update set slug=excluded.slug, name=excluded.name, description=excluded.description, image_url=excluded.image_url, season=excluded.season;
insert into products (id, slug, name, category, collection_id, price_cents, original_price_cents, images, image_url, description, details, sizes, colors, is_new, is_bestseller, rating, review_count, in_stock) values ('p1', 'the-tailored-blazer', 'The Tailored Blazer', 'Outerwear', 'c1', 89000, null, '{"/product-1.jpg"}', '/product-1.jpg', 'A blazer that holds its shape without effort. Double-faced wool with a subtle texture woven in Biella. The lining is weighted silk so it falls, not floats.', '{"Double-faced Biella wool","Weighted silk lining","Single-button fastening","Welt pockets","Dry clean only"}', '{"XS","S","M","L","XL"}', '[{"name":"Noir","hex":"#111111"},{"name":"Charcoal","hex":"#4A4A4A"}]'::jsonb, true, true, 4.9, 38, true) on conflict (id) do update set slug=excluded.slug, name=excluded.name, category=excluded.category, collection_id=excluded.collection_id, price_cents=excluded.price_cents, original_price_cents=excluded.original_price_cents, images=excluded.images, image_url=excluded.image_url, description=excluded.description, details=excluded.details, sizes=excluded.sizes, colors=excluded.colors, is_new=excluded.is_new, is_bestseller=excluded.is_bestseller, rating=excluded.rating, review_count=excluded.review_count, in_stock=excluded.in_stock, updated_at=now();
insert into products (id, slug, name, category, collection_id, price_cents, original_price_cents, images, image_url, description, details, sizes, colors, is_new, is_bestseller, rating, review_count, in_stock) values ('p5', 'wide-leg-crepe-trousers', 'Wide-Leg Crêpe Trousers', 'Bottoms', 'c1', 62000, null, '{"/product-5.jpg"}', '/product-5.jpg', 'Trousers that move like they belong to the body. Cut wide from the hip in heavyweight crêpe that keeps its drape across a full day.', '{"Heavyweight Italian crêpe","High waist with hook-and-bar closure","Side-seam pockets","Pressed centre crease","Dry clean only"}', '{"XS","S","M","L","XL"}', '[{"name":"Noir","hex":"#111111"},{"name":"Graphite","hex":"#3D3D3D"}]'::jsonb, false, true, 4.8, 27, true) on conflict (id) do update set slug=excluded.slug, name=excluded.name, category=excluded.category, collection_id=excluded.collection_id, price_cents=excluded.price_cents, original_price_cents=excluded.original_price_cents, images=excluded.images, image_url=excluded.image_url, description=excluded.description, details=excluded.details, sizes=excluded.sizes, colors=excluded.colors, is_new=excluded.is_new, is_bestseller=excluded.is_bestseller, rating=excluded.rating, review_count=excluded.review_count, in_stock=excluded.in_stock, updated_at=now();
insert into products (id, slug, name, category, collection_id, price_cents, original_price_cents, images, image_url, description, details, sizes, colors, is_new, is_bestseller, rating, review_count, in_stock) values ('p6', 'cashmere-turtleneck', 'Cashmere Turtleneck', 'Knitwear', 'c1', 54000, null, '{"/product-6.jpg"}', '/product-6.jpg', 'Grade-A Inner Mongolian cashmere, knitted at a tight gauge so it holds its form without pilling. The neck folds back into itself perfectly.', '{"100% Grade-A cashmere","Ribbed cuffs and hem","Folded turtleneck","Hand wash in cold water"}', '{"XS","S","M","L","XL"}', '[{"name":"Noir","hex":"#111111"},{"name":"Charcoal","hex":"#4A4A4A"},{"name":"Midnight","hex":"#1A1A2E"}]'::jsonb, false, false, 4.7, 19, true) on conflict (id) do update set slug=excluded.slug, name=excluded.name, category=excluded.category, collection_id=excluded.collection_id, price_cents=excluded.price_cents, original_price_cents=excluded.original_price_cents, images=excluded.images, image_url=excluded.image_url, description=excluded.description, details=excluded.details, sizes=excluded.sizes, colors=excluded.colors, is_new=excluded.is_new, is_bestseller=excluded.is_bestseller, rating=excluded.rating, review_count=excluded.review_count, in_stock=excluded.in_stock, updated_at=now();
insert into products (id, slug, name, category, collection_id, price_cents, original_price_cents, images, image_url, description, details, sizes, colors, is_new, is_bestseller, rating, review_count, in_stock) values ('p7', 'leather-belt-bag', 'Leather Belt Bag', 'Accessories', 'c1', 78000, null, '{"/product-7.jpg"}', '/product-7.jpg', 'Full-grain calfskin structured into a compact form. Carries more than it suggests. Wears flat against the body whether belted or held.', '{"Full-grain French calfskin","Suede interior lining","Magnetic closure","Adjustable leather strap","Interior slip pocket"}', '{"One Size"}', '[{"name":"Noir","hex":"#111111"},{"name":"Cognac","hex":"#8B4513"}]'::jsonb, true, false, 4.9, 14, true) on conflict (id) do update set slug=excluded.slug, name=excluded.name, category=excluded.category, collection_id=excluded.collection_id, price_cents=excluded.price_cents, original_price_cents=excluded.original_price_cents, images=excluded.images, image_url=excluded.image_url, description=excluded.description, details=excluded.details, sizes=excluded.sizes, colors=excluded.colors, is_new=excluded.is_new, is_bestseller=excluded.is_bestseller, rating=excluded.rating, review_count=excluded.review_count, in_stock=excluded.in_stock, updated_at=now();
insert into products (id, slug, name, category, collection_id, price_cents, original_price_cents, images, image_url, description, details, sizes, colors, is_new, is_bestseller, rating, review_count, in_stock) values ('p2', 'silk-drape-blouse', 'Silk Drape Blouse', 'Tops', 'c2', 48000, null, '{"/product-2.jpg"}', '/product-2.jpg', 'A blouse that earns the word. Washed 22mm silk cut with a loose front pleat that gathers at the cuff. The kind of top that improves with age.', '{"100% 22mm washed silk","Hidden placket","Single-button cuff","Hand wash or dry clean"}', '{"XS","S","M","L"}', '[{"name":"Ivory","hex":"#FFFFF0"},{"name":"Oat","hex":"#D7C7B6"},{"name":"Stone","hex":"#C4B9A8"}]'::jsonb, true, true, 4.8, 42, true) on conflict (id) do update set slug=excluded.slug, name=excluded.name, category=excluded.category, collection_id=excluded.collection_id, price_cents=excluded.price_cents, original_price_cents=excluded.original_price_cents, images=excluded.images, image_url=excluded.image_url, description=excluded.description, details=excluded.details, sizes=excluded.sizes, colors=excluded.colors, is_new=excluded.is_new, is_bestseller=excluded.is_bestseller, rating=excluded.rating, review_count=excluded.review_count, in_stock=excluded.in_stock, updated_at=now();
insert into products (id, slug, name, category, collection_id, price_cents, original_price_cents, images, image_url, description, details, sizes, colors, is_new, is_bestseller, rating, review_count, in_stock) values ('p3', 'camel-wool-trousers', 'Camel Wool Trousers', 'Bottoms', 'c2', 65000, null, '{"/product-3.jpg"}', '/product-3.jpg', 'British camel-wool woven into a straight-leg trouser with a natural rise. Wears equally well pressed or lived-in by the end of a long day.', '{"British camel-blend wool","Natural-rise waistband","Side pockets with welt finish","Dry clean only"}', '{"XS","S","M","L","XL"}', '[{"name":"Camel","hex":"#C19A6B"},{"name":"Sand","hex":"#D2B48C"}]'::jsonb, true, false, 4.6, 23, true) on conflict (id) do update set slug=excluded.slug, name=excluded.name, category=excluded.category, collection_id=excluded.collection_id, price_cents=excluded.price_cents, original_price_cents=excluded.original_price_cents, images=excluded.images, image_url=excluded.image_url, description=excluded.description, details=excluded.details, sizes=excluded.sizes, colors=excluded.colors, is_new=excluded.is_new, is_bestseller=excluded.is_bestseller, rating=excluded.rating, review_count=excluded.review_count, in_stock=excluded.in_stock, updated_at=now();
