insert into products (id, slug, name, category, collection_id, price_cents, original_price_cents, images, image_url, description, details, sizes, colors, is_new, is_bestseller, rating, review_count, in_stock) values ('p4', 'structured-leather-bag', 'Structured Leather Bag', 'Accessories', 'c3', 125000, null, '{"/product-4.jpg"}', '/product-4.jpg', 'A bag built around the idea of a single clean line. Box-structured in full-grain calf with a single top handle and no exterior hardware worth noticing.', '{"Full-grain French calfskin","Suede-lined interior","Single flush closure","Detachable shoulder strap","Two interior compartments"}', '{"One Size"}', '[{"name":"Noir","hex":"#111111"},{"name":"Burgundy","hex":"#800020"}]'::jsonb, true, false, 4.9, 11, true) on conflict (id) do update set slug=excluded.slug, name=excluded.name, category=excluded.category, collection_id=excluded.collection_id, price_cents=excluded.price_cents, original_price_cents=excluded.original_price_cents, images=excluded.images, image_url=excluded.image_url, description=excluded.description, details=excluded.details, sizes=excluded.sizes, colors=excluded.colors, is_new=excluded.is_new, is_bestseller=excluded.is_bestseller, rating=excluded.rating, review_count=excluded.review_count, in_stock=excluded.in_stock, updated_at=now();
insert into products (id, slug, name, category, collection_id, price_cents, original_price_cents, images, image_url, description, details, sizes, colors, is_new, is_bestseller, rating, review_count, in_stock) values ('p10', 'column-evening-gown', 'Column Evening Gown', 'Dresses', 'c3', 168000, null, '{"/product-10.jpg"}', '/product-10.jpg', 'A gown with nothing to prove. Heavy matte crêpe falls from a plain neckline in one unbroken line. The back is open, which is all it needs.', '{"Heavyweight matte crêpe","Open back with self-tie","Floor-length","Lined in silk charmeuse","Dry clean only"}', '{"XS","S","M","L"}', '[{"name":"Noir","hex":"#111111"},{"name":"Midnight","hex":"#1A1A2E"}]'::jsonb, true, true, 5, 8, true) on conflict (id) do update set slug=excluded.slug, name=excluded.name, category=excluded.category, collection_id=excluded.collection_id, price_cents=excluded.price_cents, original_price_cents=excluded.original_price_cents, images=excluded.images, image_url=excluded.image_url, description=excluded.description, details=excluded.details, sizes=excluded.sizes, colors=excluded.colors, is_new=excluded.is_new, is_bestseller=excluded.is_bestseller, rating=excluded.rating, review_count=excluded.review_count, in_stock=excluded.in_stock, updated_at=now();
